import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './SendMoney.css';

function SendMoney() {
  const navigate = useNavigate();

  // Form States
  const [formData, setFormData] = useState({
    sourceWallet: '',
    recipientWallet: '',
    amount: '',
    recipientName: '',
    phoneNumber: '',
    description: ''
  });

  // UI States
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [selectedWalletBalance, setSelectedWalletBalance] = useState(0);
  const [validationErrors, setValidationErrors] = useState({});

  // Mock Data (replace with API calls)
  const myWallets = [
    { id: 1, name: 'Personal Wallet', balance: 5000, currency: 'USD' },
    { id: 2, name: 'Business Wallet', balance: 10000, currency: 'USD' },
    { id: 3, name: 'Savings Wallet', balance: 3000, currency: 'USD' }
  ];

  const recipientWallets = [
    { id: 1, name: 'John Doe', walletId: 'JD123', type: 'Personal' },
    { id: 2, name: 'Jane Smith', walletId: 'JS456', type: 'Business' },
    { id: 3, name: 'Add New Recipient', walletId: 'new', type: 'New' }
  ];

  // Update selected wallet balance
  useEffect(() => {
    const selectedWallet = myWallets.find(wallet => wallet.id === parseInt(formData.sourceWallet));
    setSelectedWalletBalance(selectedWallet ? selectedWallet.balance : 0);
  }, [formData.sourceWallet]);

  // Validate the form
  const validateForm = () => {
    const errors = {};

    if (!formData.amount) {
      errors.amount = 'Amount is required.';
    } else if (parseFloat(formData.amount) <= 0) {
      errors.amount = 'Amount must be greater than 0.';
    } else if (parseFloat(formData.amount) > selectedWalletBalance) {
      errors.amount = 'Insufficient balance.';
    }

    const phoneRegex = /^\+?[1-9]\d{9,13}$/;
    if (!formData.phoneNumber) {
      errors.phoneNumber = 'Phone number is required.';
    } else if (!phoneRegex.test(formData.phoneNumber)) {
      errors.phoneNumber = 'Invalid phone number format.';
    }

    if (!formData.recipientName.trim()) {
      errors.recipientName = 'Recipient name is required.';
    } else if (formData.recipientName.length < 2) {
      errors.recipientName = 'Recipient name must be at least 2 characters long.';
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // Clear specific validation error
    if (validationErrors[name]) {
      setValidationErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  // Submit the form
  const handleSubmit = (e) => {
    e.preventDefault();
    setError(null);

    if (validateForm()) {
      setShowConfirmation(true);
    }
  };

  // Confirm the transfer
  const handleConfirmTransfer = async () => {
    setIsLoading(true);

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Navigate to success page
      navigate('/transfer-success', {
        state: {
          amount: formData.amount,
          recipient: formData.recipientName
        }
      });

      // Reset form
      setFormData({
        sourceWallet: '',
        recipientWallet: '',
        amount: '',
        recipientName: '',
        phoneNumber: '',
        description: ''
      });
    } catch (error) {
      setError('Transfer failed. Please try again.');
    } finally {
      setIsLoading(false);
      setShowConfirmation(false);
    }
  };

  // Cancel confirmation modal
  const handleCancel = () => {
    setShowConfirmation(false);
  };

  return (
    <div className="send-money-page">
      <h2>Send Money</h2>

      {error && <div className="error-banner" role="alert">{error}</div>}

      <form onSubmit={handleSubmit} className="send-money-form">
        {/* Source Wallet */}
        <div className="form-group">
          <label htmlFor="sourceWallet">From Wallet</label>
          <select
            id="sourceWallet"
            name="sourceWallet"
            value={formData.sourceWallet}
            onChange={handleChange}
            required
          >
            <option value="">Select your wallet</option>
            {myWallets.map(wallet => (
              <option key={wallet.id} value={wallet.id}>
                {wallet.name} - Balance: ${wallet.balance.toLocaleString()}
              </option>
            ))}
          </select>
        </div>

        {/* Recipient Wallet */}
        <div className="form-group">
          <label htmlFor="recipientWallet">To Wallet</label>
          <select
            id="recipientWallet"
            name="recipientWallet"
            value={formData.recipientWallet}
            onChange={handleChange}
            required
          >
            <option value="">Select recipient</option>
            {recipientWallets.map(wallet => (
              <option key={wallet.id} value={wallet.walletId}>
                {wallet.name}
              </option>
            ))}
          </select>
        </div>

        {/* Recipient Name */}
        <div className="form-group">
          <label htmlFor="recipientName">Recipient Name</label>
          <input
            type="text"
            id="recipientName"
            name="recipientName"
            value={formData.recipientName}
            onChange={handleChange}
            required
          />
          {validationErrors.recipientName && (
            <div className="error-message">{validationErrors.recipientName}</div>
          )}
        </div>

        {/* Phone Number */}
        <div className="form-group">
          <label htmlFor="phoneNumber">Phone Number</label>
          <input
            type="tel"
            id="phoneNumber"
            name="phoneNumber"
            value={formData.phoneNumber}
            onChange={handleChange}
            required
          />
          {validationErrors.phoneNumber && (
            <div className="error-message">{validationErrors.phoneNumber}</div>
          )}
        </div>

        {/* Amount */}
        <div className="form-group">
          <label htmlFor="amount">Amount</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={formData.amount}
            onChange={handleChange}
            required
          />
          {validationErrors.amount && (
            <div className="error-message">{validationErrors.amount}</div>
          )}
        </div>

        {/* Description */}
        <div className="form-group">
          <label htmlFor="description">Description (Optional)</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleChange}
            rows="3"
          />
        </div>

        <button
          type="submit"
          className="submit-button"
          disabled={
            isLoading ||
            !formData.sourceWallet ||
            !formData.recipientWallet ||
            !formData.amount ||
            !formData.recipientName ||
            !formData.phoneNumber
          }
        >
          {isLoading ? 'Processing...' : 'Send Money'}
        </button>
      </form>

      {showConfirmation && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Confirm Transfer</h3>
            <p><strong>From:</strong> {myWallets.find(w => w.id === parseInt(formData.sourceWallet))?.name}</p>
            <p><strong>To:</strong> {formData.recipientName}</p>
            <p><strong>Amount:</strong> ${formData.amount}</p>
            <p><strong>Phone:</strong> {formData.phoneNumber}</p>
            {formData.description && <p><strong>Description:</strong> {formData.description}</p>}
            <button onClick={handleCancel} className="cancel-button" disabled={isLoading}>Cancel</button>
            <button onClick={handleConfirmTransfer} className="confirm-button" disabled={isLoading}>
              {isLoading ? 'Processing...' : 'Confirm Transfer'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default SendMoney;
``
